import os
from typing import Any, Dict, List, Optional

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _extract_attribute_score(attribute_data: Dict[str, Any], threshold: float) -> bool:
    summary = attribute_data.get("summaryScore") or {}
    value = summary.get("value")
    if value is None:
        values = attribute_data.get("spanScores") or []
        if values:
            value = max(
                (span.get("score", {}).get("value", 0.0) for span in values if isinstance(span, dict)),
                default=0.0,
            )
        else:
            value = 0.0
    return float(value) >= float(threshold)


def allow_text(
    text: str,
    category_thresholds: Dict[str, float],
    *,
    api_key: Optional[str] = None,
    languages: Optional[List[str]] = None,
    timeout: float = 30.0,
) -> bool:
    """
    Decide whether to allow text using Perspective API category thresholds.

    Args:
        text: Text to evaluate.
        category_thresholds: Mapping of Perspective API attribute names to thresholds,
            e.g. {"TOXICITY": 0.8, "INSULT": 0.7}.
        api_key: Perspective API key. If omitted, reads PERSPECTIVE_API_KEY.
        languages: Optional list of language codes.
        timeout: Request timeout in seconds.

    Returns:
        True if the text is allowed under all provided thresholds, otherwise False.

    Raises:
        RuntimeError: On API failure or invalid responses.
    """
    if not text:
        return True

    key = api_key or os.environ.get("PERSPECTIVE_API_KEY")
    if not key:
        raise RuntimeError("Missing Perspective API key. Set PERSPECTIVE_API_KEY or pass api_key.")

    requested_attributes = {name.upper(): {} for name in category_thresholds.keys()}
    if not requested_attributes:
        return True

    payload: Dict[str, Any] = {
        "comment": {"text": text},
        "requestedAttributes": requested_attributes,
        "doNotStore": True,
    }
    if languages:
        payload["languages"] = languages

    params = {"key": key}

    try:
        resp = requests.post(PERSPECTIVE_API_URL, params=params, json=payload, timeout=timeout)
        resp.raise_for_status()
        data = resp.json()
    except requests.RequestException as exc:
        raise RuntimeError(f"Perspective API request failed: {exc}") from exc
    except ValueError as exc:
        raise RuntimeError("Perspective API returned invalid JSON.") from exc

    attr_scores = data.get("attributeScores") or {}
    if not isinstance(attr_scores, dict):
        raise RuntimeError("Perspective API response missing attributeScores.")

    for category, threshold in category_thresholds.items():
        category_key = category.upper()
        category_data = attr_scores.get(category_key)
        if not isinstance(category_data, dict):
            raise RuntimeError(f"Perspective API did not return score for category: {category_key}")
        if _extract_attribute_score(category_data, threshold):
            return False

    return True
